    pub fn parse_ws_trade(&self, trade: impl Into<crate::Value>, market: Option<&crate::types::Market>) -> crate::value::Dict {
        let mut trade: Value = trade.into();
        //
        // regular v2 trade
        //
        //     {
        //         "type": "trade",
        //         "symbol": "BTCUSD",
        //         "event_id": 122258166738,
        //         "timestamp": 1655330221424,
        //         "price": "22269.14",
        //         "quantity": "0.00004473",
        //         "side": "buy"
        //     }
        //
        // multi data trade
        //
        //    {
        //        "type": "trade",
        //        "symbol": "ETHUSD",
        //        "tid": "1683002242170204", // this is not TS, but somewhat ID
        //        "price": "2299.24",
        //        "amount": "0.002662",
        //        "makerSide": "bid"
        //    }
        //
        let mut timestamp: Option<i64> = self.safe_integer_k(&trade, "timestamp", &[]).as_i64();
        let mut id: Option<String> = self.safe_string2_opt(&trade, Value::Str("event_id".into()), Value::Str("tid".into()), &[]);
        let mut priceString: Option<String> = self.safe_string_k_opt(&trade, "price", &[]);
        let mut amountString: Option<String> = self.safe_string2_opt(&trade, Value::Str("quantity".into()), Value::Str("amount".into()), &[]);
        let mut side: Option<String> = self.safe_string_lower_k_opt(&trade, "side", &[]);
        if (side.is_none()) {
            let mut marketSide: Option<String> = self.safe_string_lower_k_opt(&trade, "makerSide", &[]);
            if (marketSide.as_deref() == Some("bid")) {
                side = Some("sell".to_string());
            }  else if (marketSide.as_deref() == Some("ask")) {
                side = Some("buy".to_string());
            }
        }
        let mut marketId: Option<String> = self.safe_string_lower_k_opt(&trade, "symbol", &[]);
        let mut symbol: Option<String> = self.safe_symbol(marketId.as_deref(), market, &[]).as_str().map(str::to_owned);
        return self.safe_trade(std::sync::Arc::new({
    let mut m = indexmap::IndexMap::new();
        m.insert("id".to_string(), id.map(Value::from).unwrap_or(Value::Null));
        m.insert("order".to_string(), Value::Null);
        m.insert("info".to_string(), trade);
        m.insert("timestamp".to_string(), Value::from(timestamp));
        m.insert("datetime".to_string(), self.iso8601(timestamp));
        m.insert("symbol".to_string(), symbol.map(Value::from).unwrap_or(Value::Null));
        m.insert("type".to_string(), Value::Null);
        m.insert("side".to_string(), side.map(Value::from).unwrap_or(Value::Null));
        m.insert("takerOrMaker".to_string(), Value::Null);
        m.insert("price".to_string(), priceString.map(Value::from).unwrap_or(Value::Null));
        m.insert("cost".to_string(), Value::Null);
        m.insert("amount".to_string(), amountString.map(Value::from).unwrap_or(Value::Null));
        m.insert("fee".to_string(), Value::Null);
    m
}), market);

    Default::default()
}

    pub fn handle_trade(&mut self, client: &Value, mut message: Value) {
        //
        //     {
        //         "type": "trade",
        //         "symbol": "BTCUSD",
        //         "event_id": 122278173770,
        //         "timestamp": 1655335880981,
        //         "price": "22530.80",
        //         "quantity": "0.04",
        //         "side": "buy"
        //     }
        //
        let mut trade: crate::value::Dict = self.parse_ws_trade(message, None);
        let mut symbol: Option<String> = crate::value::KeyRead::key_read(&&trade, "symbol").as_str().map(str::to_owned);
        let mut tradesLimit: i64 = self.safe_integer_k(&self.options, "tradesLimit", &[Value::Int(1000)]).as_i64().unwrap_or(1000);
        let mut stored: Option<crate::pro::cache::Cache> = self.trades.lookup(&symbol);
        if (stored.is_none()) {
            stored = Some(ArrayCache::new(Value::from(tradesLimit)));
            if (symbol.is_some()) {
                CacheStore::put(&mut self.trades, &symbol, stored.clone());
            }
        }
        stored.append(Value::Dict(trade));
        let mut messageHash: String = format!("{}{}", "trades:", symbol.as_deref().unwrap_or("null"));
        client.resolve(Value::from(&stored), messageHash.as_str());
}

